import React from "react";
import {
  useCurrentFrame,
  useVideoConfig,
  AbsoluteFill,
  spring,
  interpolate,
} from '../remotionShim';
{/* Start Google Fonts Loader */}
const useFontLoader = (fonts: string[]) => {
  const stableFonts = React.useMemo(() => {
    const unique = [...new Set(fonts.map(f => f.trim()))].sort();
    return unique;
  }, [fonts.join("|")]); // super light + stable

  React.useEffect(() => {
    const unloaded = stableFonts.filter(
      (font) =>
        !document.querySelector(
          `link[href*="${font.replace(/\s+/g, "+")}"]`
        )
    );

    if (unloaded.length === 0) return;

    const url = `https://fonts.googleapis.com/css2?${unloaded
      .map((font) => `family=${font.replace(/\s+/g, "+")}:wght@400;600;700;800;900`)
      .join("&")}&display=swap`;

    const link = document.createElement("link");
    link.rel = "stylesheet";
    link.href = url;

    document.head.appendChild(link);
  }, [stableFonts]);
};
{/* End Google Fonts Loader */}



export type PlayfulOverlayProps = Record<string, any>;

const PlayfulOverlay: React.FC<PlayfulOverlayProps> = ({
  backgroundColor = "#000000",
  transparentBackground = true,
  durationInSeconds = 7,
  text = "AWESOME!",
  textColor = "#FFFFFF",
  accentColor = "#FF3366",
  fontSize = 200,
  wobbleIntensity = 5,
}) => {
  {/* Load Google Fonts */}
  useFontLoader(["Fredoka"]);
  {/* End Load Google Fonts */}

  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  // Background transparency logic
  const bgColor = transparentBackground ? `transparent` : backgroundColor;

  // Animation Timings
  const totalFrames = Math.round(durationInSeconds * fps);
  const outroDuration = 30;
  const outroStartFrame = totalFrames - outroDuration;

  // 1. Intro Animation (Springy Pop-in)
  const introProgress = spring({
    frame,
    fps,
    config: { damping: 9, stiffness: 180, mass: 0.8 },
  });

  // 2. Outro Animation (Scale down and fall)
  const outroProgress = spring({
    frame: Math.max(0, frame - outroStartFrame),
    fps,
    config: { damping: 12, stiffness: 150 },
  });

  // 3. Hold Animation (Continuous playful movement)
  // We use the frame directly to create continuous sine wave motion
  const floatY = Math.sin(frame / 10) * (wobbleIntensity * 3);
  const wobbleRot = Math.cos(frame / 12) * wobbleIntensity;

  // Combine Scales: Start at 0, spring to 1, stay at 1, spring to 0 at end
  const currentScale = introProgress * (1 - outroProgress);

  // Combine Y Position: Center, add float during hold, drop down massively on outro
  const outroDropY = interpolate(outroProgress, [0, 1], [0, height * 0.6]);
  const finalY = (floatY * introProgress) + outroDropY;

  // Combine Rotation: Slight rotation on intro, continuous wobble, spin out on exit
  const introRot = interpolate(introProgress, [0, 1], [-15, 0]);
  const outroRotSpin = interpolate(outroProgress, [0, 1], [0, 20]);
  const finalRot = introRot + (wobbleRot * introProgress) + outroRotSpin;

  // Dynamic 3D Extruded Shadow based on font size
  const shadowDepth = Math.max(2, Math.floor(fontSize * 0.08));
  const shadowArray = React.useMemo(() => {
    const layers = [];
    // Solid colored 3D extrusion
    for (let i = 1; i <= shadowDepth; i++) {
      layers.push(`${i}px ${i}px 0px ${accentColor}`);
    }
    // Soft drop shadow underneath the extrusion
    layers.push(`${shadowDepth + 8}px ${shadowDepth + 8}px 15px rgba(0,0,0,0.3)`);
    return layers.join(", ");
  }, [shadowDepth, accentColor]);

  return (
    <AbsoluteFill
      style={{
        backgroundColor: bgColor,
        justifyContent: "center",
        alignItems: "center",
        fontFamily: "Fredoka",
        overflow: "hidden",
      }}
    >
      <div
        style={{
          transition: "none",
          transform: `scale(${currentScale}) translateY(${finalY}px) rotate(${finalRot}deg)`,
          fontSize: `${fontSize}px`,
          fontWeight: 800,
          color: textColor,
          textShadow: shadowArray,
          textAlign: "center",
          lineHeight: 1.1,
          letterSpacing: "-0.02em",
          // Adding a subtle stroke to separate text from identical backgrounds if they occur
          WebkitTextStroke: `3px ${textColor}`,
          padding: "40px", // Padding to prevent shadow clipping
        }}
      >
        {text}
      </div>
    </AbsoluteFill>
  );
};

export default PlayfulOverlay;